#[test]fn p153_voluntary_answer_can_resolve_deferred_question_before_retry_time(){let s=store();let qid=p153_ask(&s,"later-answer");p153_decision(&s,"later",&qid,"defer").unwrap();let p=prepare(&s,"voluntary","20分钟");assert_eq!(p["domain"],"health");let mut d=payload(&p);d["state"]=json!({"key":"available_time","value":20,"domain":"health"});d["answerTo"]=json!(qid);call(&s,"commit_turn",d).unwrap();assert_eq!(active_states(&s.c,now()).unwrap()[0]["value"],20.0);}

#[test]fn p153_negative_and_fractional_time_cannot_be_silently_truncated(){let s=store();for (t,q,value) in [("negative","我有-5分钟运动",5),("fraction","我有2.5分钟运动",5),("overflow","我有1020分钟运动",20)]{let p=prepare(&s,t,q);let mut d=payload(&p);d["state"]=json!({"key":"available_time","value":value,"domain":"health"});assert_eq!(call(&s,"commit_turn",d).unwrap_err().code,"state_claim_rejected");}assert!(active_states(&s.c,now()).unwrap().is_empty());}

pub(super) struct C1Clock;
impl Drop for C1Clock{fn drop(&mut self){TEST_NOW.with(|c|c.set(None));}}
pub(super) fn c1_clock()->C1Clock{let at=now();TEST_NOW.with(|c|c.set(Some(at)));C1Clock}
pub(super) fn c1_advance(ms:i64){TEST_NOW.with(|c|c.set(Some(c.get().unwrap()+ms)));}
fn c1_answered(s:&Store)->String{
 for mut r in list(&s.c,"records",100).unwrap(){if r["kind"]=="source_projection"&&r["sourceId"]=="health-demo"{r["validUntil"]=json!(now()+259200000);put(&s.c,"records",r["id"].as_str().unwrap(),&r).unwrap();}}
 let qid=p153_ask(s,"c1-ask");let p=prepare(s,"c1-reply","我有20分钟");let mut d=payload(&p);d["answerTo"]=json!(qid);d["state"]=json!({"key":"available_time","value":20,"domain":"health"});call(s,"commit_turn",d).unwrap();qid
}
#[test]fn c1_expired_answer_allows_new_gap_without_overwriting_history(){
 let _clock=c1_clock();let s=store();let qid=c1_answered(&s);let old=get(&s.c,"questions",&qid).unwrap();c1_advance(86400001);assert!(active_states(&s.c,now()).unwrap().is_empty());
 let p=prepare(&s,"c1-today","今天健康活动怎么安排");let mut d=payload(&p);d["clarification"]=json!({"field":"available_time"});call(&s,"commit_turn",d).unwrap();assert_eq!(get(&s.c,"questions",&qid).unwrap(),old);assert_eq!(list(&s.c,"questions",10).unwrap().len(),2);
}
#[test]fn c1_state_expiring_during_pending_packet_is_rejected(){
 let _clock=c1_clock();let s=store();c1_answered(&s);c1_advance(86399000);let p=prepare(&s,"c1-late","健康活动怎么安排");let mut d=payload(&p);let raw=p["snapshot"]["records"].as_array().unwrap().iter().find(|r|r["id"]=="raw:c1-reply").unwrap();d["inputRefs"].as_array_mut().unwrap().push(rf(&p,raw));c1_advance(2000);assert!(active_states(&s.c,now()).unwrap().is_empty());assert_eq!(call(&s,"commit_turn",d).unwrap_err().code,"context_stale");assert!(get(&s.c,"derivations","answer:c1-late").unwrap().is_none());
}
#[test]fn c1_valid_replacement_state_suppresses_repeat(){let _clock=c1_clock();let s=store();let qid=c1_answered(&s);c1_advance(86400001);let p=prepare(&s,"c1-new-state","我有30分钟运动");let mut d=payload(&p);d["state"]=json!({"key":"available_time","value":30,"domain":"health"});call(&s,"commit_turn",d).unwrap();let p=prepare(&s,"c1-no-need","今天健康活动怎么安排");let mut d=payload(&p);d["clarification"]=json!({"field":"available_time"});assert_eq!(call(&s,"commit_turn",d).unwrap_err().code,"clarification_rejected");assert_eq!(get(&s.c,"questions",&qid).unwrap().unwrap()["status"],"answered");}
fn c1_time_source(s:&Store){put(&s.c,"sources","c1-time-source",&json!({"id":"c1-time-source","authorized":true,"generation":1})).unwrap();put(&s.c,"records","c1-time-row",&json!({"id":"c1-time-row","sourceId":"c1-time-source","domain":"health","kind":"source_projection","status":"active","version":1,"text":"健康活动安排：我有30分钟","observedAt":now(),"validUntil":now()+86400000})).unwrap();}
#[test]fn c1_source_replacement_validity_and_authorization_matrix(){for case in ["valid","expired","revoked","tombstone"]{let _clock=c1_clock();let s=store();c1_answered(&s);c1_advance(86400001);c1_time_source(&s);let mut row=get(&s.c,"records","c1-time-row").unwrap().unwrap();let mut grant=get(&s.c,"sources","c1-time-source").unwrap().unwrap();match case{"expired"=>row["validUntil"]=json!(now()-1),"revoked"=>grant["authorized"]=json!(false),"tombstone"=>row["status"]=json!("revoked"),_=>{}}put(&s.c,"records","c1-time-row",&row).unwrap();put(&s.c,"sources","c1-time-source",&grant).unwrap();let p=prepare(&s,"c1-replacement","今天健康活动怎么安排");let mut d=payload(&p);d["clarification"]=json!({"field":"available_time"});if case=="valid"{assert_eq!(call(&s,"commit_turn",d).unwrap_err().code,"clarification_rejected");}else{assert!(!p["snapshot"]["records"].as_array().unwrap().iter().any(|r|r["id"]=="c1-time-row"));call(&s,"commit_turn",d).unwrap();}}}
#[test]fn c1_source_changes_after_prepare_fail_closed(){for case in ["expiry","generation","version","revoke"]{let _clock=c1_clock();let s=store();c1_time_source(&s);if case=="expiry"{let mut r=get(&s.c,"records","c1-time-row").unwrap().unwrap();r["validUntil"]=json!(now()+1000);put(&s.c,"records","c1-time-row",&r).unwrap();}let p=prepare(&s,"c1-stale-source","健康活动怎么安排");let mut row=get(&s.c,"records","c1-time-row").unwrap().unwrap();let mut grant=get(&s.c,"sources","c1-time-source").unwrap().unwrap();match case{"expiry"=>c1_advance(2000),"generation"=>grant["generation"]=json!(2),"version"=>row["version"]=json!(2),_=>grant["authorized"]=json!(false)}put(&s.c,"records","c1-time-row",&row).unwrap();put(&s.c,"sources","c1-time-source",&grant).unwrap();assert_eq!(call(&s,"commit_turn",payload(&p)).unwrap_err().code,"context_stale");}}
#[test]fn c1_reject_outlives_time_without_timer_or_state_write(){let _clock=c1_clock();let s=store();let mut r=get(&s.c,"records","exercise-1").unwrap().unwrap();r["validUntil"]=json!(now()+604800000);put(&s.c,"records","exercise-1",&r).unwrap();let qid=p153_ask(&s,"c1-reject");p153_decision(&s,"c1-reject-action",&qid,"reject").unwrap();c1_advance(259200000);let before=fs::read(s.c.path().unwrap()).unwrap();let snap=call(&s,"conversation_snapshot",json!({})).unwrap();assert_eq!(snap["questions"][0]["status"],"rejected");assert_eq!(before,fs::read(s.c.path().unwrap()).unwrap());let p=prepare(&s,"c1-refused-again","今天健康活动怎么安排");let mut d=payload(&p);d["clarification"]=json!({"field":"available_time"});assert_eq!(call(&s,"commit_turn",d).unwrap_err().code,"clarification_suppressed");}
#[test]fn c1_expiry_alone_does_not_rewrite_answered_history(){let _clock=c1_clock();let s=store();let qid=c1_answered(&s);let old=get(&s.c,"questions",&qid).unwrap();c1_advance(86400001);let before=fs::read(s.c.path().unwrap()).unwrap();let snap=call(&s,"conversation_snapshot",json!({})).unwrap();assert!(snap["states"].as_array().unwrap().is_empty());assert_eq!(get(&s.c,"questions",&qid).unwrap(),old);assert_eq!(before,fs::read(s.c.path().unwrap()).unwrap());}
#[test]fn c1_state_revoke_or_tombstone_enables_gap_without_resurrection(){for case in ["grant","raw"]{let _clock=c1_clock();let s=store();let qid=c1_answered(&s);if case=="grant"{let mut v=get(&s.c,"sources","conversation").unwrap().unwrap();v["authorized"]=json!(false);v["generation"]=json!(2);put(&s.c,"sources","conversation",&v).unwrap();}else{let mut v=get(&s.c,"records","raw:c1-reply").unwrap().unwrap();v["status"]=json!("revoked");put(&s.c,"records","raw:c1-reply",&v).unwrap();}assert!(active_states(&s.c,now()).unwrap().is_empty());let p=prepare(&s,"c1-missing-state","健康活动怎么安排");let mut d=payload(&p);d["clarification"]=json!({"field":"available_time"});call(&s,"commit_turn",d).unwrap();assert_eq!(get(&s.c,"questions",&qid).unwrap().unwrap()["status"],"answered");assert!(active_states(&s.c,now()).unwrap().is_empty());}}
